WITH filtered AS (SELECT id, full_name, email, dept_id, manager_id, job_title, hire_date, is_remote, WEEKOFYEAR(hire_date) AS hire_date_weekofyear, IF(is_remote, 'Yes', 'No') AS is_remote_label, COALESCE(job_title, 'N/A') AS resolved_job_title FROM employees WHERE dept_id IN (38, 40)) SELECT id, job_title, hire_date, is_remote, is_remote_label, resolved_job_title, RANK() OVER (PARTITION BY manager_id ORDER BY hire_date_weekofyear NULLS FIRST) AS hire_date_weekofyear_rank, NTILE(3) OVER (PARTITION BY DATE_TRUNC('WEEK', hire_date), dept_id ORDER BY hire_date_weekofyear DESC, id) AS hire_date_weekofyear_bucket, DENSE_RANK() OVER (PARTITION BY job_title ORDER BY hire_date_weekofyear NULLS FIRST) AS hire_date_weekofyear_dense_rank FROM filtered WHERE full_name LIKE '%Oliv%';
